-- SchemaFlow fixture: the built-in e-commerce sample written as PostgreSQL DDL.
-- Must import to exactly the same tables, columns, keys and relationships as
-- src/samples/ecommerce.ts (12 tables, 71 columns, 13 relationships, 2 enums).

CREATE TYPE public.order_status AS ENUM ('pending', 'paid', 'shipped', 'delivered', 'cancelled');
CREATE TYPE public.payment_method AS ENUM ('card', 'paypal', 'bank_transfer');

CREATE TABLE public.users (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email varchar(255) NOT NULL UNIQUE,
    full_name text NOT NULL,
    password_hash text NOT NULL,
    is_admin boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz
);

CREATE TABLE public.addresses (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id bigint NOT NULL REFERENCES public.users ON DELETE CASCADE,
    label varchar(50),
    line1 text NOT NULL,
    line2 text,
    city text NOT NULL,
    postal_code varchar(20) NOT NULL,
    country char(2) NOT NULL DEFAULT 'US'
);
CREATE INDEX addresses_user_id_idx ON public.addresses USING btree (user_id);

CREATE TABLE categories (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    parent_id integer CONSTRAINT categories_parent_fk REFERENCES categories (id) ON DELETE SET NULL,
    name varchar(100) NOT NULL,
    slug varchar(120) NOT NULL,
    CONSTRAINT categories_pkey PRIMARY KEY (id),
    UNIQUE (slug)
);

CREATE TABLE products (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sku varchar(64) NOT NULL UNIQUE,
    name text NOT NULL,
    description text,
    price_cents integer NOT NULL CONSTRAINT products_price_check CHECK (price_cents >= 0),
    currency char(3) NOT NULL DEFAULT 'USD'::bpchar,
    stock integer NOT NULL DEFAULT 0,
    tags text[],
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT products_stock_check CHECK (stock >= 0)
);
CREATE INDEX products_name_idx ON products (name);

CREATE TABLE product_categories (
    product_id bigint NOT NULL REFERENCES products ON DELETE CASCADE,
    category_id integer NOT NULL REFERENCES categories ON DELETE CASCADE,
    CONSTRAINT product_categories_pkey PRIMARY KEY (product_id, category_id)
);

CREATE TABLE coupons (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code varchar(32) NOT NULL UNIQUE,
    percent_off numeric(5, 2) NOT NULL,
    valid_from date NOT NULL DEFAULT CURRENT_DATE,
    valid_until date,
    max_uses integer,
    CONSTRAINT coupons_percent_check CHECK (percent_off > 0 AND percent_off <= 100)
);

CREATE TABLE orders (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id bigint NOT NULL,
    shipping_address_id bigint,
    coupon_id integer,
    status public.order_status NOT NULL DEFAULT 'pending'::public.order_status,
    total_cents integer NOT NULL,
    placed_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE order_items (
    order_id bigint NOT NULL,
    line_no smallint NOT NULL,
    product_id bigint NOT NULL,
    quantity integer NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price_cents integer NOT NULL,
    CONSTRAINT order_items_pkey PRIMARY KEY (order_id, line_no)
);

CREATE TABLE payments (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id bigint NOT NULL UNIQUE CONSTRAINT payments_order_fk REFERENCES orders,
    method payment_method NOT NULL,
    amount_cents integer NOT NULL,
    provider_ref varchar(128),
    paid_at timestamptz
);

CREATE TABLE shipments (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id bigint NOT NULL REFERENCES orders (id),
    carrier varchar(50) NOT NULL,
    tracking_number varchar(64),
    shipped_at timestamptz,
    delivered_at timestamptz
);

CREATE TABLE reviews (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id bigint NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    user_id bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    rating smallint NOT NULL,
    body text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT reviews_product_user_key UNIQUE (product_id, user_id),
    CONSTRAINT reviews_rating_check CHECK (rating BETWEEN 1 AND 5)
);

/* Append-only event log: deliberately no primary key and no relationships. */
CREATE TABLE audit_log (
    occurred_at timestamptz NOT NULL DEFAULT now(),
    actor text,
    action varchar(50) NOT NULL,
    entity text NOT NULL,
    payload jsonb
);

-- Foreign keys and indexes declared after the tables, pg_dump style.
ALTER TABLE ONLY orders
    ADD CONSTRAINT orders_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    ADD FOREIGN KEY (shipping_address_id) REFERENCES addresses (id) ON DELETE SET NULL;
ALTER TABLE orders ADD FOREIGN KEY (coupon_id) REFERENCES coupons (id);
ALTER TABLE order_items ADD CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE;
ALTER TABLE order_items ADD CONSTRAINT order_items_product_fk FOREIGN KEY (product_id) REFERENCES products (id);
CREATE INDEX orders_user_status_idx ON orders (user_id, status);
